const close = (a, b, tol) => Math.abs(a - b) <= tol;
const azd = (a, b) => Math.abs(((a - b + 540) % 360) - 180);
const lineClose = (l, [t, p], tol = 1e-6) => F.axialAngle(vec(l), vec({ trend: t, plunge: p })) <= tol;
const planeClose = (pl, [s, d], tol = 1e-6) => F.axialAngle(vec({ trend: pl.strike + 90, plunge: pl.dip }), vec({ trend: s + 90, plunge: d })) <= tol && close(pl.dip, d, tol * 10) && (pl.dip > 89.9 || azd(pl.strike, s) <= tol * 10);

export default async (check) => {
  let ok = 0, limbsChecked = 0;
  CASES.forEach((c, i) => {
    const e = EXP[i], p = F.parsePlanes(c.text, c.dd), f = F.fit(p.data.map((d) => d.v));
    const good = p.bad.length === 0 && f.val.every((v, k) => close(v, e.val[k], 1e-9))
      && f.axes.every((l, k) => (k === 1 && Math.abs(e.val[1] - e.val[0]) < 1e-6) || lineClose(l, e.axes[k], 1e-5))
      && close(f.K, e.K, 1e-6 * Math.max(1, Math.abs(e.K))) && close(f.C, e.C, 1e-6) && close(f.P, e.P, 1e-9) && close(f.G, e.G, 1e-9) && close(f.R, e.R, 1e-9)
      && close(f.rms, e.rms, 1e-6) && close(f.maxOff, e.max, 1e-6) && close(f.within10, e.within10, 1e-12) && planeClose(f.girdle, e.girdle, 1e-5);
    let lg = true;
    if (e.interlimb !== undefined) {
      const labs = [...new Set(p.data.map((d) => d.label).filter(Boolean))].sort();
      const L = F.limbs(p.data.filter((d) => d.label === labs[0]).map((d) => d.v), p.data.filter((d) => d.label === labs[1]).map((d) => d.v), f.b, c.over);
      lg = close(L.interlimb, e.interlimb, 1e-6) && planeClose(L.axial, e.axial, 1e-5) && lineClose(L.axialPole, e.axialPole, 1e-5)
        && lineClose(L.mean[0], e.means[0], 1e-6) && lineClose(L.mean[1], e.means[1], 1e-6) && lineClose(L.intersection, e.intersection, 1e-6) && close(L.axisGap, e.axisGap, 1e-5);
      limbsChecked++;
    }
    const k = F.kamb(p.data.map((d) => d.v), 5);
    const kb = close(k.sigma, e.sigma, 1e-9) && close(k.cone, e.cone, 1e-9) && e.probes.every((u, j) => close(F.kambAt(p.data.map((d) => d.v), u), e.kamb[j], 1e-9));
    if (good && lg && kb) ok++; else check(`fold-axis: numpy case ${i} (fit ${good}, limbs ${lg}, Kamb ${kb})`, false);
  });
  check(`fold-axis: ${ok} of ${CASES.length} sets match numpy (eigenvalues, axes, K, C, P, G, R, girdle fit, ${limbsChecked} with two limbs, Kamb)`, ok === CASES.length && limbsChecked >= 15);

  // The page's example: a made-up fold plunging 18° towards 062.
  {
    const p = F.parsePlanes(CASES[0].text), f = F.fit(p.data.map((d) => d.v));
    check('fold-axis example: 32 planes, axis 18° → 062', p.data.length === 32 && Math.round(f.axis.plunge) === 18 && Math.round(f.axis.trend) === 62);
    check('fold-axis example: girdle-shaped (K < 1), RMS 2.4° off the girdle', f.K < 1 && f.rms.toFixed(1) === '2.4' && F.cylVerdict(f.rms) === 'very nearly cylindrical' && !f.weak);
    const A = p.data.filter((d) => d.label === 'A').map((d) => d.v), B = p.data.filter((d) => d.label === 'B').map((d) => d.v);
    const L = F.limbs(A, B, f.b);
    check('fold-axis example: interlimb 87°, open, axial plane 246/78', A.length === 14 && B.length === 13 && Math.round(L.interlimb) === 87 && L.tightness === 'open' && Math.round(L.axial.strike) === 246 && Math.round(L.axial.dip) === 78);
    const O = F.limbs(A, B, f.b, true);
    check('fold-axis example: one limb overturned gives the supplement', close(O.interlimb + L.interlimb, 180, 1e-9));
  }

  // HAND: upright symmetric anticline, limbs dipping 30° east and west, axis horizontal north-south.
  {
    const p = F.parsePlanes('000 30 A\n180 30 B\n000 30 A\n180 30 B\n090 0'), f = F.fit(p.data.map((d) => d.v));
    check('fold-axis hand: upright anticline axis 0° → 000 or 180', close(f.axis.plunge, 0, 1e-6) && (azd(f.axis.trend, 0) < 1e-6 || azd(f.axis.trend, 180) < 1e-6) && f.rms < 1e-6 && f.maxOff < 1e-6);
    const L = F.limbs(p.data.filter((d) => d.label === 'A').map((d) => d.v), p.data.filter((d) => d.label === 'B').map((d) => d.v), f.b);
    check('fold-axis hand: interlimb 120° (gentle), vertical north-south axial plane', close(L.interlimb, 120, 1e-6) && L.tightness === 'gentle' && close(L.axial.dip, 90, 1e-6) && (azd(L.axial.strike, 0) < 1e-6 || azd(L.axial.strike, 180) < 1e-6));
  }
  // HAND: overturned fold, both limbs dip east (70° and 50°): 20° apart, a tight fold.
  {
    const p = F.parsePlanes('090 70 A\n090 50 B', true), f = F.fit(p.data.map((d) => d.v));
    check('fold-axis hand: dip-direction input, strikes 000', p.data.every((d) => d.plane.strike === 0));
    const A = [p.data[0].v], B = [p.data[1].v];
    const up = F.limbs(A, B, f.b), ov = F.limbs(A, B, f.b, true);
    check('fold-axis hand: overturned limb gives 20° (tight), else 160°', close(ov.interlimb, 20, 1e-6) && ov.tightness === 'tight' && close(up.interlimb, 160, 1e-6) && up.tightness === 'gentle');
    // Axial plane of the overturned fold bisects 70° and 50° east dips: it dips 60° east.
    check('fold-axis hand: overturned axial plane 000/60', close(ov.axial.dip, 60, 1e-6) && azd(ov.axial.strike, 0) < 1e-6);
  }
  // HAND: a perfect cylinder: every plane contains the line 30° → 090, so the poles fit a great circle exactly.
  {
    const b = vec({ trend: 90, plunge: 30 }), u = [0, 1, 0].map((x, i) => x - b[1] * b[i]), ul = Math.hypot(...u), w = [b[1] * u[2] - b[2] * u[1], b[2] * u[0] - b[0] * u[2], b[0] * u[1] - b[1] * u[0]].map((x) => x / ul);
    const vs = []; for (let a = 0; a < 180; a += 15) { const t = (a * Math.PI) / 180; vs.push(u.map((x, i) => (x / ul) * Math.cos(t) + w[i] * Math.sin(t))); }
    const f = F.fit(vs);
    check('fold-axis hand: perfect cylinder gives λ3 = 0, axis 30° → 090, K = 0', f.val[2] < 1e-12 && close(f.axis.plunge, 30, 1e-6) && azd(f.axis.trend, 90) < 1e-6 && f.K === 0 && f.C === Infinity && f.rms < 1e-6);
    check('fold-axis hand: Vollmer indices add up to 1', close(f.P + f.G + f.R, 1, 1e-12));
  }
  // Woodcock on a tight cluster and the weak-girdle flag.
  {
    const f = F.fit([[0, 0, 1], [0.05, 0, 0.9987], [0, 0.05, 0.9987], [-0.05, 0, 0.9987], [0, -0.05, 0.9987]].map((v) => { const l = Math.hypot(...v); return v.map((x) => x / l); }));
    check('fold-axis: a round cluster is flagged as not fixing the axis', f.weak && f.K > 1e3 || (f.weak && !Number.isFinite(f.K)));
  }
  check('fold-axis: Fleuty classes', [179, 120, 119.9, 70, 69, 30, 29, 10, 9.9, 0].map(F.fleuty).join() === 'gentle,gentle,open,open,close,close,tight,tight,isoclinal,isoclinal');
  check('fold-axis: cylindricity verdicts', F.cylVerdict(4.9).startsWith('very') && F.cylVerdict(9).startsWith('close') && F.cylVerdict(14).startsWith('only') && F.cylVerdict(20).startsWith('not'));
  {
    const p = F.parsePlanes('030 40 SE\n400 20\n030 95\n030\nN30E 40\n030 40 2\n030 40 A B\n# note\n\n030 40 a # comment');
    check('fold-axis: bad lines named with their reason', p.bad.map((b) => b.row).join() === '1,2,3,4,5,6,7' && p.bad[0].why.includes('compass') && p.bad[1].why.includes('0 to 360') && p.bad[2].why.includes('dip must') && p.bad[5].why.includes('label') && p.data.length === 1 && p.data[0].label === 'A' && p.data[0].row === 10);
  }
  {
    const p = F.parsePlanes('strike,dip,limb\n120,40,b\n300/60/a', true);
    check('fold-axis: header line skipped, dip direction converted, labels upper-cased', p.bad.length === 0 && p.data.length === 2 && p.data[0].plane.strike === 30 && p.data[1].plane.strike === 210 && p.data[0].label === 'B' && p.data[1].label === 'A');
  }
  {
    let worst = 0; for (let t = 0; t < 360; t += 23) for (let pl = 0; pl <= 90; pl += 7) { const [x, y] = project({ trend: t, plunge: pl }, 'equal-area'), u = F.unproject(x, y); worst = Math.max(worst, F.axialAngle(u, vec({ trend: t, plunge: pl }))); }
    check('fold-axis: equal-area unproject inverts project', worst < 1e-6 && F.unproject(1.5, 0) === null);
  }
  {
    const n = 27, k = F.kamb(Array.from({ length: n }, () => [0, 0, 1]), 5);
    check('fold-axis: Kamb A = 9/(n+9), E = 3σ', close(k.A, 0.25, 1e-12) && close(k.E, 6.75, 1e-12) && close(3 * k.sigma, k.E, 1e-12) && close(k.cone, Math.acos(0.75) * 180 / Math.PI, 1e-9) && close(k.z[2][2], 27 / 2.25, 1e-12));
  }
  {
    // Contour of a cone z = 1 − r: level 0.5 lies on the circle r = 0.5.
    const N = 41, lo = -1, st = 2 / (N - 1), z = []; for (let j = 0; j < N; j++) { const row = []; for (let i = 0; i < N; i++) row.push(1 - Math.hypot(lo + i * st, -lo - j * st)); z.push(row); }
    const segs = F.contour(z, lo, st, 0.5), rr = segs.flat().map(([x, y]) => Math.hypot(x, y));
    check('fold-axis: marching squares traces the 0.5 circle', segs.length > 40 && rr.every((r) => Math.abs(r - 0.5) < 0.01));
  }
};
